/**
 * Giddyup Design System — Icon Registry
 *
 * Each icon is registered under a name following the pattern:
 *   {category}/{name}-{generation}
 *
 * Generation is kept in the name (not hidden) so both gen1 and gen2
 * versions of an icon can coexist and be searched for together.
 *
 * To add more icons: export clean single-path SVGs from Figma (via the
 * Clean SVG Export plugin, selecting individual icons — not their parent
 * frame), then add an entry below with the path's `d` attribute.
 */

export interface IconDefinition {
  /** The SVG path `d` attribute(s). Most icons are a single path. */
  paths: string[];
  /** Optional: viewBox override if not the standard "0 0 16 16" */
  viewBox?: string;
}

